<?php $e = static fn($value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8'); ?>
<?php if ($flash): ?><div class="flash flash-success" role="status"><?= $e($flash) ?></div><?php endif; ?>
<section class="page-hero page-hero-compact"><div><p class="eyebrow">Back Office</p><h1>Suivis des plantations</h1><p>Les informations de suivi sont regroupées avec leur propriétaire.</p></div></section>
<section class="table-wrap"><table><thead><tr><th>Date</th><th>Plantation</th><th>Propriétaire</th><th>État</th><th>Arrosage</th><th>Observation</th><th>Action</th></tr></thead><tbody><?php foreach ($suivis as $s): ?><tr><td><?= $e($s['dateSuivi']) ?></td><td><a href="index.php?action=admin_plantation_show&amp;id=<?= (int) $s['idPlantation'] ?>"><?= $e($s['plantationNom']) ?></a></td><td><?= $e($s['username']) ?></td><td><?= $e($s['etat']) ?></td><td><?= $e($s['arrosage']) ?></td><td><?= $e($s['observation']) ?></td><td><form method="post" action="index.php?action=admin_suivi_delete" data-confirm="Supprimer ce suivi ?"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int) $s['idSuivi'] ?>"><button class="text-button" type="submit">Supprimer</button></form></td></tr><?php endforeach; ?><?php if (!$suivis): ?><tr><td colspan="7">Aucun suivi.</td></tr><?php endif; ?></tbody></table></section>
